-- Verifierat live: /sv/configurator/sy-plugin bygger SY3100-5U1 (nyckelns exempel sida 432/504),
-- SY3130-5U1-C6 (sida 513) och SY5130-5U1-01FB; stoppar port på basmonterad och topportad utan port.
--
-- SY plug-in-ventil: beställnyckeln enligt SMC 5-Port Solenoid Valve SY3000/5000/7000 Series (sida 432, 504 och 513).
-- GENERERAD ur src/lib/catalog/sy-plugin.ts -- redigera inte för hand.
--
-- Ny familj sy-plugin i kategorin valve:
-- SY{serie}{funktion}{kropp}{tätning}{pilot}{backventil}{tillval}{spole}-{spänning}{ljus}{manöver}1-{port}{gänga}{skruv},
-- t.ex. SY3100-5U1 (nyckelns exempel sida 432 och 504) och SY3130-5U1-C6
-- (topportad, sida 513). Ettan efter manöverdonet ligger fast; tredje tecknet är
-- kroppen (0 basmonterad, 3 topportad) och fjärde tätningen.
--
-- Rampen (SS5Y…) är familjen sy; ventilerna beställs per station.

begin;


insert into configurator_families (slug, name, title, description, category_slug)
values ('sy-plugin', 'SY plug-in', 'SY plug-in', '', 'valve')
on conflict (slug) do update set name = excluded.name;


create schema if not exists backup;
create table if not exists backup.sy_plugin_before_20260921 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'sy-plugin'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'sy-plugin'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'sy-plugin';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-SY-PLUGIN-V1', '{"version":"1.0","steps":[{"id":"series","step":1,"title_sv":"Serie","title_en":"Series","required":true,"type":"single_select","options":[{"v":"3","label":"SY3000"},{"v":"5","label":"SY5000"},{"v":"7","label":"SY7000"}]},{"id":"actuation","step":2,"title_sv":"Funktion","title_en":"Type of actuation","required":true,"type":"single_select","options":[{"v":"1","label":"2-läges, enkel magnet (monostabil)"},{"v":"2","label":"2-läges, dubbel magnet (bistabil)"},{"v":"3","label":"3-läges, stängt mittläge"},{"v":"4","label":"3-läges, avluftat mittläge"},{"v":"5","label":"3-läges, trycksatt mittläge"},{"v":"A","label":"4-läges dubbel 3-portsventil, NC/NC (bara gummitätning)"},{"v":"B","label":"4-läges dubbel 3-portsventil, NO/NO (bara gummitätning)"},{"v":"C","label":"4-läges dubbel 3-portsventil, NC/NO (bara gummitätning)"}]},{"id":"body","step":3,"title_sv":"Kropp (rampens typ)","title_en":"Body (manifold type)","required":true,"type":"single_select","options":[{"v":"0","label":"Basmonterad, för ramp typ 10/11 (A/B-portar på basen)"},{"v":"3","label":"Topportad, för ramp typ 12 (A/B-porten sitter på ventilen)"}]},{"id":"seal","step":4,"title_sv":"Tätning","title_en":"Seal type","required":true,"type":"single_select","options":[{"v":"0","label":"Gummitätning"},{"v":"1","label":"Metalltätning (högre frekvens, −100 kPa…0,7 MPa extern pilot)"}]},{"id":"pilot","step":5,"title_sv":"Pilot (standard är intern)","title_en":"Pilot type (internal is standard)","required":false,"type":"single_select","options":[{"v":"R","label":"Extern pilot (vakuum/lågtryck; pilottryck 0,25–0,7 MPa)"}]},{"id":"check","step":6,"title_sv":"Inbyggd backventil (standard är ingen)","title_en":"Built-in back pressure check valve (none is standard)","required":false,"type":"single_select","options":[{"v":"H","label":"Inbyggd backventil (gummitätning, 2-/4-läges, SY3000/5000)"}]},{"id":"option","step":7,"title_sv":"Pilotventil (standard är 0,7 MPa)","title_en":"Pilot valve option (0.7 MPa is standard)","required":false,"type":"single_select","options":[{"v":"B","label":"Snabb respons (0,7 MPa)"},{"v":"K","label":"Högtryck 1,0 MPa (bara metalltätning)"}]},{"id":"coil","step":8,"title_sv":"Spole (standard är utan strömsparkrets)","title_en":"Coil type (without power saving circuit is standard)","required":false,"type":"single_select","options":[{"v":"T","label":"Strömsparkrets, kontinuerlig drift (bara med ljus Z eller NZ)"}]},{"id":"voltage","step":9,"title_sv":"Märkspänning","title_en":"Rated voltage","required":true,"type":"single_select","options":[{"v":"5","label":"24 V DC"},{"v":"6","label":"12 V DC"}]},{"id":"light","step":10,"title_sv":"Ljus och skyddsdiod (standard är utan)","title_en":"Light/surge voltage suppressor (none is standard)","required":false,"type":"single_select","options":[{"v":"R","label":"Skyddsdiod, opolär"},{"v":"U","label":"Ljus och skyddsdiod, opolär"},{"v":"S","label":"Skyddsdiod, pluskommun"},{"v":"Z","label":"Ljus och skyddsdiod, pluskommun"},{"v":"NS","label":"Skyddsdiod, minuskommun"},{"v":"NZ","label":"Ljus och skyddsdiod, minuskommun"}]},{"id":"override","step":11,"title_sv":"Manöverdon (standard är tryckknapp utan lås)","title_en":"Manual override (non-locking push type is standard)","required":false,"type":"single_select","options":[{"v":"D","label":"Tryck-vrid-lås, spårförsett (standard är tryckknapp utan lås)"},{"v":"E","label":"Tryck-vrid-lås med spak"},{"v":"F","label":"Glidlås"}]},{"id":"port","step":12,"title_sv":"A/B-port (bara topportad ventil)","title_en":"A/B port (top ported valve only)","required":false,"type":"single_select","options":[{"v":"M5","label":"Gänga M5 x 0,8 (SY3000)"},{"v":"01","label":"Gänga 1/8 (SY5000)"},{"v":"02","label":"Gänga 1/4 (SY7000)"},{"v":"C2","label":"Snabbkoppling ø2"},{"v":"C3","label":"Snabbkoppling ø3,2"},{"v":"C4","label":"Snabbkoppling ø4"},{"v":"C6","label":"Snabbkoppling ø6"},{"v":"C8","label":"Snabbkoppling ø8"},{"v":"C10","label":"Snabbkoppling ø10"},{"v":"C12","label":"Snabbkoppling ø12"},{"v":"N1","label":"Snabbkoppling ø1/8\""},{"v":"N3","label":"Snabbkoppling ø5/32\""},{"v":"N7","label":"Snabbkoppling ø1/4\""},{"v":"N9","label":"Snabbkoppling ø5/16\""},{"v":"N11","label":"Snabbkoppling ø3/8\""}]},{"id":"thread","step":13,"title_sv":"Gängtyp (standard är Rc; bara gängade portar 1/8 och 1/4)","title_en":"Thread type (Rc is standard; threaded ports 1/8 and 1/4 only)","required":false,"type":"single_select","options":[{"v":"F","label":"G-gänga (standard är Rc)"},{"v":"N","label":"NPT-gänga"},{"v":"T","label":"NPTF-gänga"}]},{"id":"screw","step":14,"title_sv":"Monteringsskruv (standard är kombiskruv med rundat huvud)","title_en":"Mounting screw (round head combination screw is standard)","required":false,"type":"single_select","options":[{"v":"B","label":"Insexskruv (standard är kombiskruv med rundat huvud)"},{"v":"K","label":"Kombiskruv, tappsäkrad"},{"v":"H","label":"Insexskruv, tappsäkrad"}]}]}'::jsonb,
        'SMC SY plug-in-ventil för ventilramp', 'SMC SY plug-in valve for manifold', 'valve')
